    'SettingsMailDesc'                    => 'Konfiguracja SMTP dla wychodzących powiadomień e-mail, w tym transport, host, uwierzytelnianie i adres odpowiedzi.',
    'SettingsBackupsDesc'                 => 'Skonfiguruj czas przechowywania kopii zapasowych, harmonogram i łącza pobierania kopii zapasowych bazy danych SimpleRisk.',
    'SettingsSecurityDesc'                => 'Uwierzytelnianie, sesja, polityka haseł, bazowy adres URL oraz ustawienia bezpieczeństwa API.',
    'SettingsLoggingDesc'                 => 'Konfiguracja dzienników debugowania i audytu: poziomy dziennika, retencja oraz lokalizacja plików dziennika.',
    'HealthCheckDesc'                     => 'Diagnozuj stan systemu: wersję PHP, rozszerzenia, uprawnienia do plików, łączność z bazą danych, harmonogram cron oraz aktywacje dodatków Extra.',
    'AnnouncementsDesc'                   => 'Twórz i zarządzaj ogłoszeniami w formie banerów widocznymi dla wszystkich użytkowników.',
    'RegisterAndUpgradeDesc'              => 'Zarejestruj instalację SimpleRisk, wprowadź lub odnów klucz subskrypcji i uruchom uaktualnienia Core/Extra jednym kliknięciem.',
    'QueueMonitorDesc'                    => 'Sprawdź kolejkę zadań w tle: zadania oczekujące, w trakcie realizacji i nieudane.',
    'ExtrasDesc'                          => 'Aktywuj, dezaktywuj i konfiguruj dodatki Extra SimpleRisk (płatne rozszerzenia).',
    'ArtificialIntelligenceExtraDesc'     => 'Dodatek Extra Sztuczna inteligencja zapewnia rozszerzoną analizę ryzyka (w tym oceny FAIR) oraz dostosowaną dokumentację.',
    'CustomizationExtraDesc'              => 'Funkcja Customization Extra umożliwia dodawanie i usuwanie różnych typów pól oraz dynamiczne tworzenie niestandardowych szablonów stron.',
    'NotificationExtraDesc'               => 'Dodatek „Powiadomienia e-mail” umożliwia SimpleRisk wysyłanie powiadomień e-mail o zgłoszeniach, modyfikacjach lub innych działaniach związanych z ryzykiem. Dodatek ten można również dodać jako zaplanowany skrypt, aby wysyłać rutynowe przypomnienia, gdy ryzyko jest gotowe do przeglądu przez kierownictwo. W produkcie SimpleRisk Core, bez tego dodatku, powiadomienia nie są wysyłane poza samo narzędzie.',
    'VulnerabilityManagementExtraDesc'    => 'Dodatek Extra Zarządzanie podatnościami umożliwia klientom integrację ich instancji SimpleRisk z Qualys, Tenable.io lub Rapid7 Nexpose/InsightVM oraz import do SimpleRisk zarówno danych o zasobach, jak i podatnościach. Następnie możesz wybrać, które lokalizacje chcesz objąć, określić, które oceny podatności mają być importowane, oraz dokonać selekcji, które podatności zostaną zamienione w ryzyka w celu ich śledzenia.',
    'IncidentManagementExtraDesc'         => 'Moduł Incident Management Extra opiera się na podręczniku obsługi incydentów bezpieczeństwa komputerowego NIST 800-61 i udostępnia funkcje zarządzania incydentami z poziomu systemu SimpleRisk.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'Zmień nazwy terminologii SimpleRisk (Ryzyko, Zasób, Struktura itd.) w całym interfejsie użytkownika.',
    'RiskConfigurationDesc'               => 'Skonfiguruj reguły punktacji ryzyka: poziomy, apetyt na ryzyko, progi SLA oraz klasyczne formuły ryzyka i formuły oparte na czynnikach składowych.',
    'RiskAndThreatCatalogDesc'            => 'Prowadź katalog wartości ryzyka i zagrożeń używanych w menu rozwijanych.',
    'AddAndRemoveValuesDesc'              => 'Zarządzaj wartościami list rozwijanych dla pól ryzyka: lokalizacja, źródło, kategoria, zespół, technologia i inne.',
    'AssetValuationDesc'                  => 'Skonfiguruj skalę wyceny zasobów oraz indywidualne zastąpienia wyceny dla poszczególnych zasobów.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Dodawaj, edytuj, wyłączaj i resetuj użytkowników; zarządzaj polityką haseł.',
    'RoleManagementDesc'                  => 'Zdefiniuj role i uprawnienia, jakie każda z nich przyznaje.',
    'TeamManagementDesc'                  => 'Twórz zespoły i zarządzaj nimi; służą one do filtrowania widoczności rekordów.',
    'SeparationExtraDesc'                 => 'Dodatek „Separacja zespołowa” ogranicza przeglądanie ryzyka tylko do użytkowników należących do zespołu, do którego ryzyko jest przypisane. W produkcie SimpleRisk Core, bez tego dodatku, każdy użytkownik może zobaczyć każde ryzyko.',
    'CustomAuthenticationExtraDesc'       => 'Dodatek Custom Authentication Extra zapewnia obsługę uwierzytelniania Active Directory i SAML. W produkcie SimpleRisk Core, bez tego dodatku, jedyną opcją jest utworzenie nowych użytkowników w repozytorium tożsamości SimpleRisk.',
    'EncryptionExtraDesc'                 => 'Funkcja Encrypted Database Extra generuje losowy 256-bitowy klucz szyfrujący AES, a następnie używa go do szyfrowania poufnego tekstu przed wstawieniem go do bazy danych SimpleRisk. Zapobiega to możliwości przeglądania lub modyfikowania danych bez bezpośredniego użycia aplikacji SimpleRisk.',
    'OrganizationManagementDesc'          => 'Dodatek Extra Hierarchia organizacyjna umożliwia zdefiniowanie wielu jednostek biznesowych, które mogą obejmować dowolną liczbę zespołów. Użytkowników można następnie przypisywać do jednego lub wielu zespołów w różnych jednostkach biznesowych. Wpływa to na możliwość przeglądania i używania przez użytkownika zespołów, użytkowników i zasobów, z którymi nie jest powiązany.',

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Masowe usuwanie ryzyk. Używaj oszczędnie – usunięcia są trwałe.',
    'AuditTrailDesc'                      => 'Przeszukuj i eksportuj systemowy dziennik audytu działań użytkowników.',
    'ImportExportExtraDesc'               => 'Funkcja Import-Eksport Extra umożliwia importowanie danych do SimpleRisk poprzez mapowanie pól w pliku CSV na pola w bazie danych SimpleRisk. Można jej używać do importowania wyników audytu z arkusza kalkulacyjnego innej firmy, wyników skanowania podatności z innego narzędzia, zasobów z bazy CMDB i nie tylko. Funkcja Extra umożliwia również eksport plików CSV z SimpleRisk zawierających ryzyka, działania minimalizujące ryzyko, przeglądy lub raport łączony obejmujący wszystkie trzy elementy.',
    'JiraExtraDesc'                       => 'Dodatek Extra Integracja z Jira umożliwia użytkownikom dwukierunkową integrację z instancją Jira. Pozwala łączyć ryzyka z problemami Jira oraz synchronizować ich dane, status i komentarze.',
    'APIExtraDesc'                        => 'API Extra umożliwia klientom korzystanie z interfejsu API RESTful w celu tworzenia skryptowanych interakcji z innymi aplikacjami, co pozwala na zaawansowaną automatyzację i wykorzystanie istniejącej infrastruktury.',
    'AdvancedSearchExtraDesc'             => 'Dodatek Extra Wyszukiwanie zaawansowane zamienia pole wyszukiwania na górnym pasku w jedno wyszukiwanie obejmujące ryzyka, struktury, kontrole, dokumenty, wyjątki, testy, audyty, zasoby i grupy zasobów, wraz z pełną stroną wyszukiwania do przeglądania wyników. Pokazuje tylko rekordy, które użytkownik może zobaczyć.',
    'AssessmentsExtraDesc'                => 'Dodatek Extra Ocena ryzyka umożliwia użytkownikom definiowanie kontaktów, tworzenie pytań (w tym z logiką), składanie wielu pytań w szablon kwestionariusza, tworzenie kwestionariuszy i wysyłanie ich do kontaktów, przeglądanie wyników kwestionariuszy, dodawanie ryzyk na podstawie tych wyników, porównywanie wyników w czasie, importowanie i eksportowanie ocen dostosowanych zewnętrznie oraz przeglądanie ścieżki audytu oceny ryzyka.',
    'ActiveAssessmentsDesc'               => 'Przeglądaj i zarządzaj ocenami, które są obecnie w toku.',
    'WorkflowsExtraDesc'                  => 'Dodatek Workflows Extra oferuje wizualny, sterowany zdarzeniami silnik przepływu pracy, który automatyzuje działania związane z zarządzaniem ryzykiem w odpowiedzi na zdarzenia w SimpleRisk. Możesz projektować przepływy pracy, które uruchamiają się po zmianach — takich jak przesłanie, aktualizacja lub przegląd ryzyka — aby kierować zatwierdzenia, przypisywać zadania i utrzymywać proces w ruchu bez ręcznej interwencji.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => 'Dodatek Secure Controls Framework (SCF) Extra to bezpośrednia integracja między Secure Controls Framework a SimpleRisk. Importuje katalog kontroli SCF oraz ich mapowania w szerokim zakresie struktur zgodności i cyberbezpieczeństwa do funkcji Zarządzanie w SimpleRisk, dzięki czemu możesz przyjąć potrzebne struktury i zarządzać ich kontrolami bez tworzenia ich ręcznie.',

    // Configure Hub - tile descriptions (maintenance category)
    'FixReviewDatesDesc'                  => 'Migruje starsze kolumny dat przeglądu typu varchar na właściwe typy daty. Widoczne tylko w razie potrzeby.',
    'DatabaseUpgradeDesc'                 => 'Ręcznie uruchom procedurę uaktualniania bazy danych SimpleRisk.',

