    'EncryptionRestoreBodyWhat'             => 'Każdy wiersz zapisany w bazie danych po utworzeniu kopii zapasowej zostanie trwale utracony — w tym ryzyka, środki zaradcze (mitygacje), wpisy dziennika audytu oraz wszelkie inne zmiany wprowadzone od aktywacji. Dodatek Zaszyfrowana baza danych zostanie dezaktywowany w ramach przywracania.',
