    'BaseScoreExploitabilityMetrics' => 'Metryki możliwości wykorzystania podstawowej oceny',
    'BaseScoreImpactMetrics' => 'Metryki wpływu wyniku bazowego',
    // Per-field help popovers on the CVSS holder's 14 metric selects
    // (buildCvssScoreItem(), risk-details-form.js) -- one per CVSS v2
    // metric, matching the standard CVSS v2 specification definitions.
    // Double-quoted (not single-quoted, this file's usual style) so the
    // \n line breaks are real escape sequences: each popover leads with one
    // overall sentence, then one bullet line per option, rendered via
    // white-space: pre-line on .sr-scoring-help-popover .popover-body
    // (scss/modules/_questionnaire.scss) -- plain text throughout, no HTML,
    // so the popover stays initialized without Bootstrap's `html: true`.
    "AttackVectorHelp" => 'Sposób, w jaki można uzyskać dostęp do podatności.
• Lokalny: wymaga dostępu lokalnego, np. do konsoli lub powłoki.
• Sieć sąsiednia: atakujący musi znajdować się w tym samym fizycznym lub logicznym segmencie sieci.
• Sieć: podatność można wykorzystać zdalnie przez sieć, bez potrzeby dostępu lokalnego ani z sieci sąsiedniej.',
    "AttackComplexityHelp" => 'Jak złożony jest atak, gdy atakujący ma już dostęp do celu.
• Wysoki: wymaga specjalnych warunków, które trudno zapewnić.
• Średni: należy spełnić pewne warunki, ale po ich spełnieniu wykorzystanie podatności nie jest trudne.
• Niski: nie są potrzebne żadne szczególne warunki.',
    "AuthenticationHelp" => 'Liczba uwierzytelnień, które atakujący musi wykonać wobec celu, aby wykorzystać podatność.
• Wielokrotne: uwierzytelnienie jest wymagane dwa lub więcej razy, nawet przy użyciu tych samych poświadczeń.
• Pojedyncze: uwierzytelnienie jest wymagane jeden raz.
• Brak: uwierzytelnienie nie jest wymagane.',
    "ConfidentialityImpactHelp" => 'Wpływ na poufność danych przetwarzanych przez system w przypadku wykorzystania podatności.
• Brak: brak wpływu.
• Częściowy: pewne ujawnienie informacji, ale atakujący nie kontroluje, jakich, lub utrata jest ograniczona.
• Całkowity: całkowite ujawnienie wszystkich informacji w systemie.',
    "IntegrityImpactHelp" => "Wpływ na integralność systemu w przypadku wykorzystania luki.\n• Brak: brak wpływu.\n• Częściowy: niektóre dane można modyfikować, ale atakujący nie kontroluje tego, co modyfikuje, lub zakres jest ograniczony.\n• Całkowity: całkowite naruszenie integralności systemu; atakujący może modyfikować dowolne pliki.",
    "AvailabilityImpactHelp" => "Wpływ na dostępność systemu w przypadku wykorzystania luki.\n• Brak: brak wpływu.\n• Częściowy: zmniejszona wydajność lub przerwy w dostępności.\n• Całkowity: całkowite wyłączenie danego zasobu.",
    "RemediationLevelHelp" => 'Poziom dostępnej remediacji podatności.
• Oficjalna poprawka: dostępne jest kompletne rozwiązanie producenta.
• Poprawka tymczasowa: dostępna jest oficjalna, ale tymczasowa poprawka.
• Obejście: istnieje nieoficjalne obejście niepochodzące od producenta.
• Niedostępna: nie ma rozwiązania lub nie można go zastosować.',
    "ReportConfidenceHelp" => 'Stopień pewności co do istnienia podatności i wiarygodności jej szczegółów technicznych.
• Niepotwierdzona: pojedynczy, niepotwierdzony raport źródłowy; podstawowy problem jest spekulacją.
• Nieuwiarygodniona: wiele niezależnych źródeł zgłasza to samo zachowanie, ale przyczyna źródłowa nie jest potwierdzona.
• Potwierdzona: producent potwierdził problem lub został on potwierdzony analizą kodu źródłowego albo exploita.',
    "CollateralDamagePotentialHelp" => 'Potencjał utraty życia, zasobów fizycznych lub strat finansowych w przypadku wykorzystania podatności.
• Brak: takie straty są mało prawdopodobne.
• Niski do średniego: możliwa jest umiarkowana strata.
• Wysoki: katastrofalny wpływ na zasoby, przychody lub bezpieczeństwo organizacji.',
    "TargetDistributionHelp" => "Proporcja podatnych systemów w Twoim środowisku.\n• Brak: nie istnieją żadne systemy docelowe.\n• Niski: 1–25% systemów jest podatnych.\n• Średni: 26–75% systemów jest podatnych.\n• Wysoki: 76–100% systemów jest podatnych.",
    "ConfidentialityRequirementHelp" => 'Jak ważna dla Twojej organizacji jest poufność danego zasobu.
• Niski: utrata poufności ma ograniczony wpływ.
• Średni: ma poważny wpływ.
• Wysoki: ma katastrofalny wpływ.',
    "IntegrityRequirementHelp" => 'Jak ważna dla Twojej organizacji jest integralność danego zasobu.
• Niski: utrata integralności ma ograniczony wpływ.
• Średni: ma poważny wpływ.
• Wysoki: ma katastrofalny wpływ.',
    "AvailabilityRequirementHelp" => 'Jak ważna dla Twojej organizacji jest dostępność danego zasobu.
• Niski: utrata dostępności ma ograniczony wpływ.
• Średni: ma poważny wpływ.
• Wysoki: ma katastrofalny wpływ.',
    // Base Score Metrics' two sub-group intro sentences (metricsSubGroup()'s
    // `descKey`, risk-details-form.js) -- orient the user to what the GROUP
    // as a whole is asking, distinct from the per-field *Help popover keys
    // above which explain each metric's own options.
    'BaseScoreExploitabilityMetricsDescription' => 'W jaki sposób atakujący musiałby dotrzeć do tej luki i ją wykorzystać: gdzie musi się znajdować, jak złożony jest atak i czy musi się najpierw uwierzytelnić.',
    'BaseScoreImpactMetricsDescription' => 'Co się stanie, jeśli luka zostanie skutecznie wykorzystana: jaki wpływ będzie to miało na poufność, integralność i dostępność systemu, którego dotyczy luka.',
    // Advanced Metrics' three optional sub-group intro sentences -- same
    // metricsSubGroup() `descKey` as the two Base Score groups above.
    'TemporalScoreMetricsDescription' => 'Jak rzeczywiste zagrożenie związane z tą podatnością zmienia się w czasie: aktualny stan kodu exploita, dostępne działania naprawcze oraz stopień pewności raportów, że podatność istnieje.',
    'EnvironmentalScoreMetricsDescription' => 'Jak ryzyko związane z tą podatnością zależy od Twojego środowiska: potencjał rzeczywistych szkód oraz liczba Twoich systemów, których faktycznie dotyczy podatność.',
    'ImpactSubscoreModifiersDescription' => 'Zważ wpływ podstawowej oceny według tego, jak istotne są poufność, integralność i dostępność dla tego konkretnego zasobu.',
    // Phase 4d-iii: DREAD holder help popovers (view_dread_help()'s
    // existing English text, includes/display.php, extracted to real $lang
    // keys -- that function's own content was raw hardcoded HTML, never
    // localized, so it could not be reused verbatim).
    'DamagePotentialHelp' => 'Jak duże szkody spowoduje wykorzystanie zagrożenia?
0 = Żadne
5 = Dane pojedynczego użytkownika zostały naruszone lub dotknięte.
10 = Całkowite zniszczenie systemu lub danych',
    'ReproducibilityHelp' => 'Jak łatwo odtworzyć wykorzystanie zagrożenia?
0 = Bardzo trudne lub niemożliwe, nawet dla administratorów aplikacji.
5 = Wymaga jednego lub dwóch kroków, może wymagać uprawnionego użytkownika.
10 = Wystarczy przeglądarka internetowa i pasek adresu, bez uwierzytelniania.',
    'ExploitabilityHelp' => 'Co jest potrzebne do wykorzystania tego zagrożenia?
0 = Zaawansowana wiedza programistyczna i sieciowa oraz niestandardowe lub zaawansowane narzędzia ataku.
5 = Złośliwe oprogramowanie istnieje w Internecie lub exploit można łatwo wykonać przy użyciu dostępnych narzędzi ataku.
10 = Wystarczy przeglądarka internetowa',
    'AffectedUsersHelp' => 'Ilu użytkowników zostanie dotkniętych?
0 = Żaden
5 = Niektórzy użytkownicy, ale nie wszyscy
10 = Wszyscy użytkownicy',
    'DiscoverabilityHelp' => 'Jak łatwo wykryć to zagrożenie?
0 = Bardzo trudne lub niemożliwe; wymaga kodu źródłowego lub dostępu administracyjnego.
5 = Można je odgadnąć lub wykryć, monitorując ślady ruchu sieciowego.
9 = Szczegóły takich błędów są już publicznie znane i można je łatwo znaleźć za pomocą wyszukiwarki.
10 = Informacje są widoczne na pasku adresu przeglądarki lub w formularzu.',
    // The DREAD holder's summary card heading and "DREAD Metrics" card
    // heading. No existing key covers either (confirmed via grep before
    // adding).
    'DreadScore' => 'Wynik DREAD',
    'DreadMetrics' => 'Metryki DREAD',
    // Phase 4d-iv: OWASP holder help popovers (view_owasp_help()'s
    // existing English text, includes/display.php, extracted to real
    // $lang keys -- same never-localized-legacy-content extraction the
    // DREAD phase already did for its own 5 fields). Wording/levels
    // trued up against that function's real source text, not transcribed
    // from an earlier standard-methodology draft.
    'SkillLevelHelp' => 'Jak duże umiejętności techniczne ma ta grupa agentów zagrożeń?
1 = Brak umiejętności technicznych
3 = Pewne umiejętności techniczne
5 = Zaawansowany użytkownik komputera
6 = Umiejętności sieciowe i programistyczne
9 = Umiejętności przeprowadzania testów penetracyjnych bezpieczeństwa',
    'MotiveHelp' => 'Jak bardzo ta grupa agentów zagrożeń jest zmotywowana do znalezienia i wykorzystania tej podatności?
1 = Niska lub brak nagrody
4 = Możliwa nagroda
9 = Wysoka nagroda',
    'OpportunityHelp' => 'Jakie zasoby i możliwości są wymagane, aby ta grupa agentów zagrożeń znalazła i wykorzystała tę podatność?
0 = Wymagany pełny dostęp lub kosztowne zasoby
4 = Wymagany specjalny dostęp lub zasoby
7 = Wymagany częściowy dostęp lub zasoby
9 = Nie jest wymagany dostęp ani zasoby',
    'SizeHelp' => 'Jak duża jest ta grupa agentów zagrożeń?' . "\n" . '2 = Deweloperzy' . "\n" . '2 = Administratorzy systemu' . "\n" . '4 = Użytkownicy intranetu' . "\n" . '5 = Partnerzy' . "\n" . '6 = Uwierzytelnieni użytkownicy' . "\n" . '9 = Anonimowi użytkownicy Internetu',
    'EaseOfDiscoveryHelp' => 'Jak łatwo ta grupa agentów zagrożeń może wykryć tę podatność?
1 = Praktycznie niemożliwe
3 = Trudne
7 = Łatwe
9 = Dostępne narzędzia automatyczne',
    'EaseOfExploitHelp' => 'Jak łatwo ta grupa agentów zagrożeń może faktycznie wykorzystać tę podatność?
1 = Teoretyczne
3 = Trudne
5 = Łatwe
9 = Dostępne narzędzia automatyczne',
    'AwarenessHelp' => 'Jak dobrze ta grupa agentów zagrożeń zna tę podatność?
1 = Nieznana
4 = Ukryta
6 = Oczywista
9 = Powszechnie znana',
    'IntrusionDetectionHelp' => 'Jak prawdopodobne jest wykrycie wykorzystania podatności?
1 = Aktywne wykrywanie w aplikacji
3 = Rejestrowane i przeglądane
8 = Rejestrowane bez przeglądu
9 = Nierejestrowane',
    'LossOfConfidentialityHelp' => 'Ile danych może zostać ujawnionych i jak są wrażliwe?
2 = Ujawniona minimalna ilość danych niewrażliwych
6 = Ujawniona minimalna ilość danych krytycznych
6 = Ujawniona duża ilość danych niewrażliwych
7 = Ujawniona duża ilość danych krytycznych
9 = Ujawnione wszystkie dane',
    'LossOfIntegrityHelp' => 'Ile danych może zostać uszkodzonych i jak poważne jest uszkodzenie?
1 = Minimalna ilość danych lekko uszkodzonych
3 = Minimalna ilość danych poważnie uszkodzonych
5 = Duża ilość danych lekko uszkodzonych
7 = Duża ilość danych poważnie uszkodzonych
9 = Wszystkie dane całkowicie uszkodzone',
    'LossOfAvailabilityHelp' => 'Ile usług może zostać utraconych i jak są one istotne?
1 = Przerwane minimalne usługi drugorzędne
5 = Przerwane minimalne usługi podstawowe
5 = Przerwane liczne usługi drugorzędne
7 = Przerwane liczne usługi podstawowe
9 = Całkowita utrata wszystkich usług',
    'LossOfAccountabilityHelp' => 'Czy działania agentów zagrożeń można przypisać do konkretnej osoby?
1 = W pełni możliwe do prześledzenia
7 = Możliwe do prześledzenia
9 = Całkowicie anonimowe',
    'FinancialDamageHelp' => 'Jak duże straty finansowe mogą wyniknąć z wykorzystania luki w zabezpieczeniach?' . "\n" . '1 = Mniej niż koszt naprawy luki w zabezpieczeniach' . "\n" . '3 = Niewielki wpływ na roczny zysk' . "\n" . '7 = Istotny wpływ na roczny zysk' . "\n" . '9 = Bankructwo',
    'ReputationDamageHelp' => 'Czy wykorzystanie podatności spowodowałoby szkody wizerunkowe zagrażające biznesowi?
1 = Minimalne szkody
4 = Utrata kluczowych klientów
5 = Utrata dobrej woli
9 = Szkoda dla marki',
    'NonComplianceHelp' => 'Jak duże narażenie powoduje niezgodność?
2 = Drobne naruszenie
5 = Wyraźne naruszenie
7 = Głośne naruszenie',
    'PrivacyViolationHelp' => 'Ile informacji umożliwiających identyfikację osoby może zostać ujawnionych?' . "\n" . '3 = Jedna osoba' . "\n" . '5 = Setki ludzi' . "\n" . '7 = Tysiące ludzi' . "\n" . '9 = Miliony ludzi',
    // The OWASP holder's Score card heading. No existing key covers this
    // (confirmed via grep before adding) -- the Likelihood/Impact card
    // headings reuse the already-existing bare 'Likelihood'/'Impact' keys.
    'OwaspScore' => 'Wynik OWASP',
    // Phase 4d-iv follow-up: group-level descriptions for the 4 OWASP
    // subgroup headings, sourced from OWASP's own Risk Rating Methodology
    // (https://community.owasp.org/OWASP_Risk_Rating_Methodology), tightened
    // into short UI captions -- not a verbatim quote (see this task's own
    // source table for the original wording).
    'ThreatAgentFactorsDescription' => 'Szacuje prawdopodobieństwo powodzenia ataku tej grupy agentów zagrożenia.',
    'VulnerabilityFactorsDescription' => 'Szacuje prawdopodobieństwo, że ta podatność zostanie wykryta i wykorzystana.',
    'TechnicalImpactDescription' => 'Rozbija wpływ na poufność, integralność, dostępność i rozliczalność.',
    'BusinessImpactDescription' => 'Odzwierciedla to, co jest ważne dla biznesu, poza samym wpływem technicznym.',
    // CVSS's own Temporal-metric 'Exploitability' help text. This key shares
    // a labelKey ('Exploitability') with DREAD's own field, so both would
    // otherwise derive the same generic lang key ('ExploitabilityHelp'),
    // with DREAD's entry silently winning for both -- risk-details-form.js's
    // buildCvssScoreItem() and risk-details-view.js's cvssMetricValueRow()
    // reference this key directly for CVSS's Exploitability field instead
    // of the generic '<labelKey>Help' derivation.
    'CVSSExploitabilityHelp' => 'Aktualny stan technik wykorzystania podatności lub dostępności kodu exploita.
• Niesprawdzony: kod exploita nie jest dostępny lub wykorzystanie jest teoretyczne.
• Dowód koncepcji: kod exploita istnieje, ale jest niepraktyczny dla większości atakujących.
• Funkcjonalny: funkcjonalny kod exploita działa w większości sytuacji.
• Wysoki: wykorzystanie jest niezawodne i albo zautomatyzowane (np. robak), albo w ogóle nie wymaga kodu exploita.',
    // Risk Scoring -- Classic Inline (Task 3): the Classic scoring method's
    // new inline Score card heading and its Likelihood/Impact cards' short
    // plain-English descriptions (js/simplerisk/common/risk-details-form.js's
    // buildClassicHolder()). Deliberately NOT sourced from NIST SP 800-30 or
    // any other external standard -- confirmed with the user via the
    // approved mockup review, unlike OWASP's own subgroup descriptions
    // above, which do cite OWASP's Risk Rating Methodology.
    'ClassicScore' => 'Klasyczny wynik',
    'ClassicLikelihoodDescription' => 'Jakie jest prawdopodobieństwo wystąpienia tego ryzyka.',
    'ClassicImpactDescription' => 'Jak poważne byłyby konsekwencje, gdyby to ryzyko się ziściło.',
    // Risk Scoring -- Custom Inline (Task 2): the Custom scoring method's
    // new inline Score card heading (js/simplerisk/common/risk-details-form.js's
    // buildCustomHolder()) and the Custom Value card's short description
    // caption. 'CustomValueDescription' text confirmed directly with the
    // user, same as Classic's own description keys above.
    'CustomScore' => 'Wynik niestandardowy',
    'CustomValueDescription' => 'Wartość niestandardowa może być liczbą dziesiętną z zakresu od 0 do 10.',
    // Risk Scoring -- Contributing Risk Inline (Phase 4d-v): the last of
    // the three deferred scoring methods (DREAD/OWASP shipped earlier in
    // this same project). The Likelihood/Contributing Risk cards' short
    // plain-English descriptions (js/simplerisk/common/risk-details-form.js's
    // buildContributingRiskHolder()). The Score card heading reuses the
    // EXISTING 'ContributingRiskScore' key (already present above, same
    // text) rather than duplicating it -- 'ContributingRisk'/
    // 'ContributingLikelihood'/'Weight'/'Subject' are likewise reused as-is.
    'ContributingLikelihoodDescription' => 'Jakie jest prawdopodobieństwo wystąpienia tego ryzyka.',
    'ContributingRiskDescription' => 'Każdy z poniższych czynników jest ważony według swojej względnej ważności — wybierz, w jakim stopniu dany czynnik ma wpływ na to ryzyko.',
    // OWASP read-mode card (buildOwaspReadView(), risk-details-view.js):
    // the live calculation formula under each of the 4 sub-group names
    // (Threat Agent Factors/Vulnerability Factors/Technical Impact/
    // Business Impact), matching the legacy risk-scoring-details panel's
    // own "= ( a + b + c + d ) / 4" text (includes/display.php), and the
    // OWASP Risk Rating Methodology link note placed in the OWASP Score
    // column's open space below the summary numbers.
    'OwaspSubgroupFormula' => '= ( {a} + {b} + {c} + {d} ) / 4',
    'OwaspMethodologyNote' => 'Pełne szczegóły metodyki oceny ryzyka OWASP można znaleźć',
    'Here' => 'tutaj',
    // Scoring widget formula captions (Classic/DREAD/Contributing Risk),
    // the same ".sr-cvss-vector under the score label" treatment CVSS's
    // vector caption and OwaspSubgroupFormula above already have, on both
    // the edit-mode holder (risk-details-form.js) and the read-mode card
    // (risk-details-view.js). Classic reuses the existing RISKClassicExp1-5
    // keys instead of a new one -- see those keys' own long-standing
    // definitions above.
    'DreadScoreFormula' => '= ( {a} + {b} + {c} + {d} + {e} ) / 5',
    // Contributing Risk's per-factor weighted term and its shared
    // Likelihood term (update_contributing_risk_score(), includes/
    // functions.php) -- unlike DREAD/OWASP's fixed roster, the factor list
    // is admin-configured, so this is one formula PER FACTOR ROW rather
    // than one fixed caption under the total score.
    // {maxName}: score.php parity -- legacy's "Maximum Value" column showed
    // the max option's human-readable name alongside its number (e.g.
    // "[5] Certain", includes/display.php); these formulas only showed the
    // bare number.
