    'AssetScoring' => 'Ocena zasobów',
    'AssetScoringSettingsHint' => 'Każdy zasób jest oceniany jako Niski, Umiarkowany lub Wysoki pod względem poufności, integralności i dostępności, a poufność może zamiast tego mieć wartość Nie dotyczy, co pomija ją w obu wynikach. Jego kategoryzacja FIPS to najwyższa z trzech ocen. Jego wynik ważony to średnia ważona trzech wartości poziomów, a progi przedziałów zamieniają ten wynik na przedział Niski, Umiarkowany lub Wysoki. Zmiana tych ustawień natychmiast ponownie oblicza ocenę każdego zasobu.',
    'Weights' => 'Wagi',
    'AssetScoringWeightsHint' => 'Stopień, w jakim każdy cel liczy się w punktacji ważonej: od 0 do 100, z dokładnością do dwóch miejsc po przecinku. Waga 0 pomija ten cel. Integralność i dostępność nie mogą jednocześnie wynosić 0, ponieważ poufność „Nie dotyczy” jest zawsze pomijana.',
    'LevelValues' => 'Wartości poziomów',
