    'BandThresholds' => 'Progi przedziałów',
    'AssetScoringBandThresholdsHint' => 'Wynik ważony równy progowi lub wyższy należy do danego przedziału, a wynik poniżej progu Umiarkowanego jest Niski. Przedział Umiarkowany musi zaczynać się powyżej wartości Niskiej, a Wysoki musi zaczynać się powyżej Umiarkowanego i nie wyżej niż wartość Wysoka.',
    'ModerateStartsAt' => 'Umiarkowany zaczyna się od',
