    'DefaultScoringForNewAssets' => 'Domyślna ocena nowych zasobów',
    'AssetScoringDefaultsHint' => 'Wstępnie wybiera te oceny, gdy ktoś dodaje zasób w formularzu zasobu. Zasoby utworzone przez wykrywanie, import lub API pozostają nieocenione, chyba że podano dla nich własne oceny. Pozostaw wszystkie trzy jako Nie ustawiono, aby wyłączyć tę funkcję.',
    'AssetScoringWeightsInvalid' => 'Wagi oceny zasobów muszą być liczbami od 0 do 100 z maksymalnie dwoma miejscami po przecinku, a integralność i dostępność nie mogą mieć jednocześnie wagi 0.',
    'AssetScoringValuesInvalid' => 'Wartości poziomów oceny zasobów muszą być liczbami powyżej 0 i do 100 z maksymalnie dwoma miejscami po przecinku, przy czym Niski jest poniżej Umiarkowanego, a Umiarkowany poniżej Wysokiego.',
