    'AssetScoringCategorizationHelp' => 'Kategoryzacja bezpieczeństwa FIPS 199 to najwyższa wartość graniczna: najwyższa ocena spośród stosowanych celów. Pojedyncza ocena Wysoki sprawia, że zasób jest oceniony jako Wysoki, niezależnie od pozostałych. Wartość Nie dotyczy jest ignorowana.',
