    // SR-115: HTTP Strict Transport Security (HSTS)
    'EnableHSTS' => 'Włącz HTTP Strict Transport Security (HSTS)',
    'EnableHSTSHelp' => 'Nakazuje przeglądarkom łączyć się z SimpleRisk wyłącznie przez HTTPS przez czas określony w polu maksymalnego wieku poniżej. Włącz tę opcję dopiero wtedy, gdy HTTPS działa na tej witrynie niezawodnie: przeglądarki, które odebrały ten nagłówek, będą odrzucać zwykłe HTTP, a niepoprawnego certyfikatu nie będzie można obejść do czasu wygaśnięcia maksymalnego wieku. Zacznij od krótkiego maksymalnego wieku, np. 300 sekund, i zwiększ go po sprawdzeniu działania HTTPS.',
    'HSTSMaxAge' => 'Maksymalny wiek HSTS (sekundy)',
